#include "AuthoringCatalog.h"

#include <algorithm>
#include <array>
#include <cstring>
#include <limits>

namespace NeoEngine {
namespace {
constexpr uint32_t kMagic = 0x41555448U, kVersion = 1U;
template <typename T> void Put(std::vector<uint8_t>& out, const T& value) { const auto* begin = reinterpret_cast<const uint8_t*>(&value); out.insert(out.end(), begin, begin + sizeof(T)); }
template <typename T> bool Get(std::span<const uint8_t> in, size_t& at, T& value) { if (at > in.size() || in.size() - at < sizeof(T)) return false; std::memcpy(&value, in.data() + at, sizeof(T)); at += sizeof(T); return true; }
void PutString(std::vector<uint8_t>& out, const std::string& value) { const uint16_t size = static_cast<uint16_t>(value.size()); Put(out, size); out.insert(out.end(), value.begin(), value.end()); }
bool GetString(std::span<const uint8_t> in, size_t& at, std::string& value) { uint16_t size = 0; if (!Get(in, at, size) || size == 0 || size > 96 || at > in.size() || in.size() - at < size) return false; value.assign(reinterpret_cast<const char*>(in.data() + at), size); at += size; return true; }
template <typename T> void PutDefinitions(std::vector<uint8_t>& out, const std::vector<T>& values) { const uint16_t count = static_cast<uint16_t>(values.size()); Put(out, count); for (const T& value : values) Put(out, value); }
template <typename T> bool GetDefinitions(std::span<const uint8_t> in, size_t& at, std::vector<T>& values, uint16_t maximum) { uint16_t count = 0; if (!Get(in, at, count) || count > maximum) return false; values.resize(count); for (T& value : values) if (!Get(in, at, value)) return false; return true; }
uint64_t Hash(std::span<const uint8_t> bytes) { uint64_t value = 1469598103934665603ULL; for (uint8_t byte : bytes) { value ^= byte; value *= 1099511628211ULL; } return value; }
}

bool AuthoringCatalog::Fail(AuthoringError error) { lastError_ = error; return false; }
bool AuthoringCatalog::ValidMaterial(const CollisionMaterialDefinition& d) const { return d.id != 0 && d.hardnessPermille <= 1000 && d.frictionPermille <= 1000 && d.restitutionPermille <= 1000 && d.densityPermille > 0 && d.densityPermille <= 1000; }
bool AuthoringCatalog::ValidKey(const std::string& key) const { return !key.empty() && key.size() <= 96 && std::all_of(key.begin(), key.end(), [](unsigned char c) { return std::isalnum(c) || c == '-' || c == '_' || c == '.'; }); }
bool AuthoringCatalog::ValidBehavior(AuthoringBehavior value) const { return value <= AuthoringBehavior::ChaseOrigin; }
template <typename T> bool AuthoringCatalog::IsUnique(uint32_t id, const T& values) const { return id != 0 && std::none_of(values.begin(), values.end(), [id](const auto& item) { return item.id == id; }); }
bool AuthoringCatalog::ValidSkeleton(const SkeletonDefinition& d) const { if (d.id == 0 || d.bones.empty() || d.bones.size() > kMaxBonesPerSkeleton) return false; uint32_t roots = 0; for (size_t index = 0; index < d.bones.size(); ++index) { const auto& bone = d.bones[index]; if (bone.boneId == 0 || bone.lengthMillimeters > 100000) return false; if (bone.parentIndex == -1) ++roots; else if (bone.parentIndex < 0 || static_cast<size_t>(bone.parentIndex) >= index) return false; for (size_t other = 0; other < index; ++other) if (d.bones[other].boneId == bone.boneId) return false; } return roots == 1; }
const CollisionMaterialDefinition* AuthoringCatalog::Material(uint32_t id) const { const auto it = std::find_if(materials_.begin(), materials_.end(), [id](const auto& x) { return x.id == id; }); return it == materials_.end() ? nullptr : &*it; }
const SkeletonDefinition* AuthoringCatalog::Skeleton(uint32_t id) const { const auto it = std::find_if(skeletons_.begin(), skeletons_.end(), [id](const auto& x) { return x.id == id; }); return it == skeletons_.end() ? nullptr : &*it; }
const CharacterDefinition* AuthoringCatalog::Character(uint32_t id) const { const auto it = std::find_if(characters_.begin(), characters_.end(), [id](const auto& x) { return x.id == id; }); return it == characters_.end() ? nullptr : &*it; }
const BuildingDefinition* AuthoringCatalog::Building(uint32_t id) const { const auto it = std::find_if(buildings_.begin(), buildings_.end(), [id](const auto& x) { return x.id == id; }); return it == buildings_.end() ? nullptr : &*it; }
const ActorDefinition* AuthoringCatalog::Actor(uint32_t id) const { const auto it = std::find_if(actors_.begin(), actors_.end(), [id](const auto& x) { return x.id == id; }); return it == actors_.end() ? nullptr : &*it; }
const SceneDefinition* AuthoringCatalog::Scene(uint32_t id) const { const auto it = std::find_if(scenes_.begin(), scenes_.end(), [id](const auto& x) { return x.id == id; }); return it == scenes_.end() ? nullptr : &*it; }
bool AuthoringCatalog::AddMaterial(CollisionMaterialDefinition d) { if (materials_.size() >= kMaxMaterials) return Fail(AuthoringError::Capacity); if (!ValidMaterial(d)) return Fail(AuthoringError::InvalidDefinition); if (!IsUnique(d.id, materials_)) return Fail(AuthoringError::DuplicateId); materials_.push_back(d); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::AddSkeleton(SkeletonDefinition d) { if (skeletons_.size() >= kMaxSkeletons) return Fail(AuthoringError::Capacity); if (!ValidSkeleton(d)) return Fail(AuthoringError::InvalidHierarchy); if (!IsUnique(d.id, skeletons_)) return Fail(AuthoringError::DuplicateId); skeletons_.push_back(std::move(d)); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::AddCharacter(CharacterDefinition d) { if (characters_.size() >= kMaxCharacters) return Fail(AuthoringError::Capacity); if (!IsUnique(d.id, characters_)) return Fail(AuthoringError::DuplicateId); if (Skeleton(d.skeletonId) == nullptr || Material(d.materialId) == nullptr) return Fail(AuthoringError::MissingReference); if (d.health == 0 || d.stamina == 0) return Fail(AuthoringError::InvalidDefinition); characters_.push_back(d); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::AddBuilding(BuildingDefinition d) { if (buildings_.size() >= kMaxBuildings) return Fail(AuthoringError::Capacity); if (!IsUnique(d.id, buildings_)) return Fail(AuthoringError::DuplicateId); if (Material(d.materialId) == nullptr) return Fail(AuthoringError::MissingReference); if (d.footprintWidth == 0 || d.footprintDepth == 0 || d.health == 0) return Fail(AuthoringError::InvalidDefinition); buildings_.push_back(d); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::AddItem(ItemDefinition d) { if (items_.size() >= kMaxItems) return Fail(AuthoringError::Capacity); if (!IsUnique(d.id, items_)) return Fail(AuthoringError::DuplicateId); if (Material(d.materialId) == nullptr || d.itemClass > AuthoringItemClass::Quest || d.maxStack == 0 || d.weightGrams == 0) return Fail(AuthoringError::InvalidDefinition); items_.push_back(d); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::AddNarrative(NarrativeEntryDefinition d) { if (narratives_.size() >= kMaxNarratives) return Fail(AuthoringError::Capacity); if (!IsUnique(d.id, narratives_) || !ValidKey(d.contentKey) || d.branchDestinationIds.size() > kMaxNarrativeBranches) return Fail(AuthoringError::InvalidNarrative); for (uint32_t destination : d.branchDestinationIds) if (destination == d.id || std::none_of(narratives_.begin(), narratives_.end(), [destination](const auto& value) { return value.id == destination; })) return Fail(AuthoringError::MissingReference); narratives_.push_back(std::move(d)); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::AddActor(ActorDefinition d) { if (actors_.size() >= kMaxActors) return Fail(AuthoringError::Capacity); if (!IsUnique(d.id, actors_)) return Fail(AuthoringError::DuplicateId); if (d.kind > AuthoringActorKind::Monster || Character(d.characterId) == nullptr || Material(d.materialId) == nullptr || !ValidBehavior(d.behavior) || d.moveTilesPerTick > 16) return Fail(AuthoringError::InvalidDefinition); actors_.push_back(d); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::AddScene(SceneDefinition d) { if (scenes_.size() >= kMaxScenes) return Fail(AuthoringError::Capacity); if (!IsUnique(d.id, scenes_) || d.placements.empty() || d.placements.size() > kMaxScenePlacements) return Fail(AuthoringError::InvalidScene); for (const auto& placement : d.placements) { if (placement.kind > AuthoringSceneObjectKind::Building || (placement.kind == AuthoringSceneObjectKind::Actor ? Actor(placement.definitionId) == nullptr : Building(placement.definitionId) == nullptr)) return Fail(AuthoringError::MissingReference); } scenes_.push_back(std::move(d)); lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::BindScene(uint32_t sceneId, SceneWorld& scene, int16_t extent) { const SceneDefinition* definition = Scene(sceneId); if (definition == nullptr || extent <= 0) return Fail(AuthoringError::InvalidScene); if (scene_ != nullptr) return Fail(AuthoringError::SceneAlreadyBound); if (definition->placements.size() > SceneWorld::kCapacity - scene.AliveCount()) return Fail(AuthoringError::SceneCapacity); std::vector<BoundObject> staged; staged.reserve(definition->placements.size()); for (const auto& placement : definition->placements) { SceneEntity entity{}; if (!scene.Create(entity) || !scene.SetTransform(entity, {static_cast<float>(placement.x), 0.0F, static_cast<float>(placement.z), 0, 0, 0, 1, 1, 1})) { for (const auto& object : staged) scene.Destroy(object.entity); return Fail(AuthoringError::SceneCapacity); } staged.push_back({entity, placement.kind, placement.definitionId, placement.x, placement.z, 1, {}, 0}); } scene_ = &scene; worldHalfExtent_ = extent; bound_ = std::move(staged); tick_ = 0; lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::SetActorGoal(uint32_t actorDefinitionId, GridCell goal, const GridNavigation& navigation) { const auto it = std::find_if(bound_.begin(), bound_.end(), [actorDefinitionId](const auto& value) { return value.kind == AuthoringSceneObjectKind::Actor && value.definitionId == actorDefinitionId; }); if (it == bound_.end() || it->x < 0 || it->z < 0) return Fail(AuthoringError::NavigationFailed); std::vector<GridCell> route; if (!navigation.FindPath({static_cast<uint16_t>(it->x), static_cast<uint16_t>(it->z)}, goal, route) || route.size() < 2) return Fail(AuthoringError::NavigationFailed); it->route = std::move(route); it->routeIndex = 1; lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::Tick(uint32_t ticks) { if (scene_ == nullptr || ticks == 0 || ticks > 120) return Fail(AuthoringError::InvalidScene); for (uint32_t step = 0; step < ticks; ++step) { ++tick_; for (auto& object : bound_) { if (object.kind != AuthoringSceneObjectKind::Actor) continue; const ActorDefinition* actor = Actor(object.definitionId); if (actor == nullptr) return Fail(AuthoringError::SceneSyncFailed); const int16_t rate = static_cast<int16_t>(actor->moveTilesPerTick); if (object.routeIndex < object.route.size()) { const uint16_t steps = std::max<uint16_t>(1, actor->moveTilesPerTick); for (uint16_t moved = 0; moved < steps && object.routeIndex < object.route.size(); ++moved, ++object.routeIndex) { object.x = static_cast<int16_t>(object.route[object.routeIndex].x); object.z = static_cast<int16_t>(object.route[object.routeIndex].z); } } else if (actor->behavior == AuthoringBehavior::Patrol && rate > 0) { const int32_t next = static_cast<int32_t>(object.x) + object.patrolDirection * rate; if (next > worldHalfExtent_ || next < -worldHalfExtent_) object.patrolDirection = static_cast<int8_t>(-object.patrolDirection); object.x = static_cast<int16_t>(std::clamp(static_cast<int32_t>(object.x) + object.patrolDirection * rate, -static_cast<int32_t>(worldHalfExtent_), static_cast<int32_t>(worldHalfExtent_))); } else if (actor->behavior == AuthoringBehavior::Wander && rate > 0) { const int16_t delta = ((tick_ + actor->id) & 1U) == 0 ? rate : static_cast<int16_t>(-rate); object.z = static_cast<int16_t>(std::clamp(static_cast<int32_t>(object.z) + delta, -static_cast<int32_t>(worldHalfExtent_), static_cast<int32_t>(worldHalfExtent_))); } else if (actor->behavior == AuthoringBehavior::ChaseOrigin && rate > 0) { if (object.x > 0) object.x = static_cast<int16_t>(std::max<int32_t>(0, object.x - rate)); else if (object.x < 0) object.x = static_cast<int16_t>(std::min<int32_t>(0, object.x + rate)); if (object.z > 0) object.z = static_cast<int16_t>(std::max<int32_t>(0, object.z - rate)); else if (object.z < 0) object.z = static_cast<int16_t>(std::min<int32_t>(0, object.z + rate)); } if (!scene_->SetTransform(object.entity, {static_cast<float>(object.x), 0.0F, static_cast<float>(object.z), 0, 0, 0, 1, 1, 1})) return Fail(AuthoringError::SceneSyncFailed); } } lastError_ = AuthoringError::None; return true; }
bool AuthoringCatalog::Contact(uint32_t first, uint32_t second, ContactMaterialResponse& response) const { const auto* a = Material(first); const auto* b = Material(second); if (a == nullptr || b == nullptr) return false; response.hardnessPermille = std::min(a->hardnessPermille, b->hardnessPermille); response.frictionPermille = static_cast<uint16_t>((static_cast<uint32_t>(a->frictionPermille) + b->frictionPermille) / 2U); response.restitutionPermille = std::min(a->restitutionPermille, b->restitutionPermille); return true; }
const SceneEntity* AuthoringCatalog::BoundEntity(uint32_t definitionId) const { const auto it = std::find_if(bound_.begin(), bound_.end(), [definitionId](const auto& value) { return value.definitionId == definitionId; }); return it == bound_.end() ? nullptr : &it->entity; }
std::vector<uint8_t> AuthoringCatalog::Serialize() const { std::vector<uint8_t> out; Put(out, kMagic); Put(out, kVersion); PutDefinitions(out, materials_); const uint16_t sk = static_cast<uint16_t>(skeletons_.size()); Put(out, sk); for (const auto& s : skeletons_) { Put(out, s.id); const uint16_t count = static_cast<uint16_t>(s.bones.size()); Put(out, count); for (const auto& b : s.bones) Put(out, b); } PutDefinitions(out, characters_); PutDefinitions(out, buildings_); PutDefinitions(out, items_); const uint16_t na = static_cast<uint16_t>(narratives_.size()); Put(out, na); for (const auto& n : narratives_) { Put(out, n.id); PutString(out, n.contentKey); const uint8_t count = static_cast<uint8_t>(n.branchDestinationIds.size()); Put(out, count); for (uint32_t branch : n.branchDestinationIds) Put(out, branch); } PutDefinitions(out, actors_); const uint16_t sc = static_cast<uint16_t>(scenes_.size()); Put(out, sc); for (const auto& s : scenes_) { Put(out, s.id); const uint16_t count = static_cast<uint16_t>(s.placements.size()); Put(out, count); for (const auto& p : s.placements) Put(out, p); } return out; }
bool AuthoringCatalog::Deserialize(std::span<const uint8_t> bytes) { size_t at = 0; uint32_t magic = 0, version = 0; if (!Get(bytes, at, magic) || !Get(bytes, at, version) || magic != kMagic || version != kVersion) return Fail(AuthoringError::CorruptPersistence); AuthoringCatalog restored; std::vector<CollisionMaterialDefinition> materials; if (!GetDefinitions(bytes, at, materials, kMaxMaterials)) return Fail(AuthoringError::CorruptPersistence); for (auto value : materials) if (!restored.AddMaterial(value)) return Fail(AuthoringError::CorruptPersistence); uint16_t skeletonCount = 0; if (!Get(bytes, at, skeletonCount) || skeletonCount > kMaxSkeletons) return Fail(AuthoringError::CorruptPersistence); for (uint16_t i = 0; i < skeletonCount; ++i) { SkeletonDefinition value{}; uint16_t bones = 0; if (!Get(bytes, at, value.id) || !Get(bytes, at, bones) || bones > kMaxBonesPerSkeleton) return Fail(AuthoringError::CorruptPersistence); value.bones.resize(bones); for (auto& bone : value.bones) if (!Get(bytes, at, bone)) return Fail(AuthoringError::CorruptPersistence); if (!restored.AddSkeleton(std::move(value))) return Fail(AuthoringError::CorruptPersistence); } std::vector<CharacterDefinition> characters; std::vector<BuildingDefinition> buildings; std::vector<ItemDefinition> items; if (!GetDefinitions(bytes, at, characters, kMaxCharacters) || !GetDefinitions(bytes, at, buildings, kMaxBuildings) || !GetDefinitions(bytes, at, items, kMaxItems)) return Fail(AuthoringError::CorruptPersistence); for (auto value : characters) if (!restored.AddCharacter(value)) return Fail(AuthoringError::CorruptPersistence); for (auto value : buildings) if (!restored.AddBuilding(value)) return Fail(AuthoringError::CorruptPersistence); for (auto value : items) if (!restored.AddItem(value)) return Fail(AuthoringError::CorruptPersistence); uint16_t narratives = 0; if (!Get(bytes, at, narratives) || narratives > kMaxNarratives) return Fail(AuthoringError::CorruptPersistence); for (uint16_t i = 0; i < narratives; ++i) { NarrativeEntryDefinition value{}; uint8_t branches = 0; if (!Get(bytes, at, value.id) || !GetString(bytes, at, value.contentKey) || !Get(bytes, at, branches) || branches > kMaxNarrativeBranches) return Fail(AuthoringError::CorruptPersistence); value.branchDestinationIds.resize(branches); for (auto& branch : value.branchDestinationIds) if (!Get(bytes, at, branch)) return Fail(AuthoringError::CorruptPersistence); if (!restored.AddNarrative(std::move(value))) return Fail(AuthoringError::CorruptPersistence); } std::vector<ActorDefinition> actors; if (!GetDefinitions(bytes, at, actors, kMaxActors)) return Fail(AuthoringError::CorruptPersistence); for (auto value : actors) if (!restored.AddActor(value)) return Fail(AuthoringError::CorruptPersistence); uint16_t scenes = 0; if (!Get(bytes, at, scenes) || scenes > kMaxScenes) return Fail(AuthoringError::CorruptPersistence); for (uint16_t i = 0; i < scenes; ++i) { SceneDefinition value{}; uint16_t placements = 0; if (!Get(bytes, at, value.id) || !Get(bytes, at, placements) || placements > kMaxScenePlacements) return Fail(AuthoringError::CorruptPersistence); value.placements.resize(placements); for (auto& placement : value.placements) if (!Get(bytes, at, placement)) return Fail(AuthoringError::CorruptPersistence); if (!restored.AddScene(std::move(value))) return Fail(AuthoringError::CorruptPersistence); } if (at != bytes.size()) return Fail(AuthoringError::CorruptPersistence); *this = std::move(restored); lastError_ = AuthoringError::None; return true; }
uint64_t AuthoringCatalog::DeterministicState() const { const std::vector<uint8_t> bytes = Serialize(); return Hash(bytes); }
} // namespace NeoEngine
